SELECT analytics_order_facts.category, SUM(analytics_order_facts.gross_revenue) AS gross_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2024 AND analytics_order_facts.month = 8 AND analytics_order_facts.region = 'South' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'consumer' AND analytics_order_facts.category = 'category_02' GROUP BY analytics_order_facts.category ORDER BY gross_revenue DESC, analytics_order_facts.category ASC LIMIT 10
